/** Shared by the fact generators. */

/** The one place the regenerate command is written. Change it here when `facts` has an npm script. */
export const GENERATE_COMMAND = 'npm run facts';

/** Where generated fact files are committed, relative to the repo root. */
export const FACTS_DIR = 'docs/generated';

/** The header every generated file carries, so nobody edits one by hand. */
export const generatedNotice = (sources: string): string =>
  `> Generated by \`${GENERATE_COMMAND}\` — do not edit. Source: ${sources}.`;

/** A markdown table cell: pipes would end the cell, newlines would end the row. */
export const cell = (text: string): string => text.replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ').trim();

export const byText = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
